insert into passages (id, text, difficulty_level, b, active) values
('f8a8e734-a2ca-41b9-a36c-63541469ef94', 'Many families are now trying to recycle more at home. Instead of throwing everything into one bin, they separate paper, plastic, glass, and food waste into different containers. This makes it easier for recycling centers to process the materials and turn them into new products. Some cities also offer rewards, such as lower waste fees, to households that recycle consistently. Experts say that recycling not only reduces the amount of trash sent to landfills but also saves energy, since making new products from recycled materials usually requires less power than making them from raw materials. However, recycling only works well if people sort their waste correctly, so many communities provide guides explaining exactly what can and cannot be recycled.', 2, -1.0, true),
('d9107a8f-ea0f-428f-8e2b-8f47484407aa', 'In recent years, more companies have allowed employees to work from home instead of commuting to an office every day. This shift, often called remote work, became especially common after many businesses were forced to adapt during a global health crisis. Employees report several benefits, including saving time on commuting and having more flexibility to manage their personal schedules. However, remote work also creates challenges. Some workers feel isolated without daily face-to-face contact with colleagues, and managers sometimes find it harder to monitor progress on team projects. To address these issues, many companies now use video calls and online chat tools to keep employees connected, and some require staff to come into the office a few days each week.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('9270e822-7a8f-4b69-8252-c686a26ac02b', 'sentence_completion', 'Although he studied hard, he was still ___ about the exam results.', NULL, '[{"id": "b", "text": "nervous"}, {"id": "c", "text": "confident"}, {"id": "a", "text": "careless"}, {"id": "d", "text": "silent"}]'::jsonb, 0, '{"strategy": "studied hard אך עדיין... = למרות המאמץ, עדיין חסר ביטחון לגבי התוצאה.", "correct_reason": "nervous = עצבני/חושש. גם מי שמתאמץ יכול לחשוש מהתוצאה.", "options_analysis": ["נכון! nervous = חושש — הגיוני גם אחרי לימוד מאומץ", "confident = בטוח בעצמו — סותר את ה-''although''", "careless = חסר אכפתיות — לא הגיוני אחרי מאמץ רב", "silent = שקט — לא מתאר רגש כלפי בחינה"]}', 1.43, -1.0, 0.25, 2, 'ai', NULL, true),
('70aa735f-d360-4964-bbf4-23f396d64d7a', 'sentence_completion', 'The manager decided to ___ the meeting until all documents were ready.', NULL, '[{"id": "c", "text": "enjoy"}, {"id": "a", "text": "postpone"}, {"id": "b", "text": "cancel"}, {"id": "d", "text": "attend"}]'::jsonb, 1, '{"strategy": "until all documents were ready = עד שהמסמכים יהיו מוכנים. מה עושים לפגישה כשמחכים למשהו?", "correct_reason": "postpone = לדחות. דוחים פגישה עד שמשהו אחר מוכן.", "options_analysis": ["enjoy = ליהנות — לא רלוונטי לפגישה", "נכון! postpone = לדחות — מתאים בדיוק ל-''until ready''", "cancel = לבטל — יותר קיצוני מהנדרש, המנהל רק דוחה", "attend = להשתתף — לא מסביר המתנה למסמכים"]}', 1.37, -1.0, 0.25, 2, 'ai', NULL, true),
('0d127126-509b-4f09-a549-348d8b5dbc87', 'sentence_completion', 'She was ___ to hear that her application had been accepted.', NULL, '[{"id": "c", "text": "embarrassed"}, {"id": "a", "text": "annoyed"}, {"id": "d", "text": "delighted"}, {"id": "b", "text": "confused"}]'::jsonb, 2, '{"strategy": "application accepted = הבקשה התקבלה. איך מרגישים לשמוע חדשות טובות?", "correct_reason": "delighted = שמחה מאוד. קבלת בקשה היא חדשות טובות.", "options_analysis": ["embarrassed = נבוכה — לא מתאים לקבלה", "annoyed = מוטרדת — לא מתאים לחדשות טובות", "נכון! delighted = שמחה מאוד — תגובה טבעית לקבלה", "confused = מבולבלת — לא מתאים לתשובה ברורה"]}', 1.53, -1.0, 0.25, 2, 'ai', NULL, true),
('e1a9632f-8c64-4def-87d8-ff6706e53c5e', 'sentence_completion', 'The road was ___ closed due to construction work.', NULL, '[{"id": "a", "text": "permanently"}, {"id": "c", "text": "hardly"}, {"id": "d", "text": "rarely"}, {"id": "b", "text": "temporarily"}]'::jsonb, 3, '{"strategy": "due to construction work = בגלל עבודות. עבודות בנייה נגמרות, אז הסגירה היא לא לצמיתות.", "correct_reason": "temporarily = באופן זמני. עבודות בנייה גורמות לסגירה זמנית, לא קבועה.", "options_analysis": ["permanently = לצמיתות — סותר את הרעיון שעבודות מסתיימות", "hardly = בקושי — לא מתאים לתיאור סגירה", "rarely = לעיתים נדירות — לא מתאר משך זמן סגירה", "נכון! temporarily = זמנית — מתאים לסגירה בגלל עבודות"]}', 1.51, -1.0, 0.25, 2, 'ai', NULL, true),
('baf6ce9d-3c28-4bc9-86d2-71faf63c9555', 'sentence_completion', 'He tried to ___ his mistake by apologizing sincerely.', NULL, '[{"id": "a", "text": "correct"}, {"id": "c", "text": "hide"}, {"id": "d", "text": "repeat"}, {"id": "b", "text": "forget"}]'::jsonb, 0, '{"strategy": "apologizing sincerely = התנצלות כנה. מה מנסים לעשות עם טעות ע''י התנצלות?", "correct_reason": "correct = לתקן. התנצלות כנה היא דרך לתקן טעות.", "options_analysis": ["נכון! correct = לתקן — התנצלות היא דרך לתקן טעות", "hide = להסתיר — סותר התנצלות פומבית", "repeat = לחזור על — הפוך, לא רוצים לחזור על הטעות", "forget = לשכוח — לא קשור להתנצלות פעילה"]}', 1.42, -1.0, 0.25, 2, 'ai', NULL, true),
('1d94372a-a849-4b7d-87df-1f2310731184', 'sentence_completion', 'The company decided to ___ its prices due to rising costs.', NULL, '[{"id": "b", "text": "decrease"}, {"id": "c", "text": "increase"}, {"id": "d", "text": "cancel"}, {"id": "a", "text": "freeze"}]'::jsonb, 1, '{"strategy": "due to rising costs = בגלל עלייה בעלויות. מה עושים למחירים כשהעלויות עולות?", "correct_reason": "increase = להעלות. עלייה בעלויות מובילה להעלאת מחירים.", "options_analysis": ["decrease = להוריד — הפוך ממה שקורה כשעלויות עולות", "נכון! increase = להעלות — תגובה הגיונית לעלייה בעלויות", "cancel = לבטל — לא רלוונטי למחירים", "freeze = להקפיא — לא מסביר תגובה לעלייה בעלויות"]}', 1.23, -1.0, 0.25, 2, 'ai', NULL, true),
('576d170a-b924-449b-a340-3e2a77c5d0e7', 'sentence_completion', 'It took her a long time to ___ from the surgery.', NULL, '[{"id": "d", "text": "complain"}, {"id": "c", "text": "escape"}, {"id": "a", "text": "recover"}, {"id": "b", "text": "travel"}]'::jsonb, 2, '{"strategy": "long time...from the surgery = זמן רב אחרי הניתוח. מה עושים אחרי ניתוח?", "correct_reason": "recover = להחלים. אחרי ניתוח מחלימים, לפעמים לאט.", "options_analysis": ["complain = להתלונן — לא מתאר תהליך של זמן", "escape = לברוח — לא רלוונטי לניתוח", "נכון! recover = להחלים — התהליך הטבעי אחרי ניתוח", "travel = לנסוע — לא קשור להחלמה"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('fcc84ecc-0170-4a73-ac5b-f38256d18f20', 'sentence_completion', 'The teacher asked the students to ___ their opinions during the discussion.', NULL, '[{"id": "c", "text": "forget"}, {"id": "a", "text": "copy"}, {"id": "d", "text": "hide"}, {"id": "b", "text": "share"}]'::jsonb, 3, '{"strategy": "during the discussion = במהלך הדיון. מה עושים עם דעות בדיון כיתתי?", "correct_reason": "share = לשתף. בדיון משתפים דעות.", "options_analysis": ["forget = לשכוח — לא רלוונטי לדיון", "copy = להעתיק — לא מתאר הבעת דעה אישית", "hide = להסתיר — הפוך ממטרת דיון", "נכון! share = לשתף — בדיוק מה שעושים בדיון"]}', 0.99, -1.0, 0.25, 2, 'ai', NULL, true),
('b58a6d65-bd37-47e1-927b-52af6e588ae3', 'sentence_completion', 'Because of the heavy traffic, we had to ___ our meeting.', NULL, '[{"id": "a", "text": "reschedule"}, {"id": "c", "text": "enjoy"}, {"id": "d", "text": "forget"}, {"id": "b", "text": "celebrate"}]'::jsonb, 0, '{"strategy": "heavy traffic = פקק כבד. מה עושים לפגישה כשמאחרים בגלל פקק?", "correct_reason": "reschedule = לקבוע מחדש. פקק שגורם לאיחור מוביל לתזמון מחדש.", "options_analysis": ["נכון! reschedule = לתזמן מחדש — פתרון הגיוני לאיחור בגלל פקק", "enjoy = ליהנות — לא רלוונטי לפקק", "forget = לשכוח — לא מסביר תגובה הגיונית", "celebrate = לחגוג — לא רלוונטי"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('8d5b0f49-a15f-435e-91b5-acacab15a81a', 'sentence_completion', 'The scientists were ___ by the unexpected results of the experiment.', NULL, '[{"id": "b", "text": "embarrassed"}, {"id": "d", "text": "surprised"}, {"id": "a", "text": "bored"}, {"id": "c", "text": "pleased"}]'::jsonb, 1, '{"strategy": "unexpected results = תוצאות בלתי צפויות. איך מדענים מגיבים לתוצאה שלא ציפו לה?", "correct_reason": "surprised = מופתעים. תוצאה בלתי צפויה מפתיעה.", "options_analysis": ["embarrassed = נבוכים — לא מתאר תגובה למחקר", "נכון! surprised = מופתעים — תגובה ישירה לתוצאה בלתי צפויה", "bored = משועממים — לא קשור לתוצאה מפתיעה", "pleased = מרוצים — לא בהכרח, ייתכן שהתוצאה שלילית"]}', 1.14, -1.0, 0.25, 2, 'ai', NULL, true),
('ded2f272-8190-4536-8322-bb263b3dae08', 'sentence_completion', 'He ___ his keys somewhere in the house and could not find them.', NULL, '[{"id": "d", "text": "found"}, {"id": "a", "text": "sold"}, {"id": "b", "text": "misplaced"}, {"id": "c", "text": "borrowed"}]'::jsonb, 2, '{"strategy": "could not find them = לא הצליח למצוא אותם. מה קרה למפתחות?", "correct_reason": "misplaced = הניח במקום לא נכון/איבד. לכן לא הצליח למצוא אותם.", "options_analysis": ["found = מצא — סותר ''could not find''", "sold = מכר — לא הגיוני, הוא עדיין מחפש אותם", "נכון! misplaced = הניח במקום הלא נכון — לכן לא מוצא אותם", "borrowed = שאל — לא מסביר חיפוש אחרי מפתחות שלו"]}', 1.45, -1.0, 0.25, 2, 'ai', NULL, true),
('29695628-20ff-4706-87f0-a64e91207590', 'sentence_completion', 'The company launched a new product to ___ its market share.', NULL, '[{"id": "c", "text": "reduce"}, {"id": "b", "text": "hide"}, {"id": "d", "text": "ignore"}, {"id": "a", "text": "expand"}]'::jsonb, 3, '{"strategy": "launched a new product = השיקה מוצר חדש. למה חברות משיקות מוצרים חדשים?", "correct_reason": "expand = להרחיב. מוצר חדש נועד להגדיל נתח שוק.", "options_analysis": ["reduce = לצמצם — הפוך ממטרת השקת מוצר", "hide = להסתיר — לא רלוונטי לנתח שוק", "ignore = להתעלם מ- — לא הגיוני כמטרה עסקית", "נכון! expand = להרחיב — מטרה טבעית של מוצר חדש"]}', 1.07, -1.0, 0.25, 2, 'ai', NULL, true),
('3bfd4943-fde2-4dc4-b5a7-21455db94ad8', 'restatement', 'He was late because his car broke down.', NULL, '[{"id": "d", "text": "His car breaking down caused him to be late."}, {"id": "b", "text": "He arrived early because his car broke down."}, {"id": "a", "text": "He was late even though his car broke down."}, {"id": "c", "text": "His car broke down because he was late."}]'::jsonb, 0, '{"strategy": "car broke down -> late = תקלת רכב גרמה לאיחור.", "correct_reason": "''car breaking down caused him to be late'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק: תקלה גרמה לאיחור", "''הגיע מוקדם'' סותר ''was late''", "''למרות שהתקלקל'' משנה יחס סיבתי לניגוד", "''התקלקל בגלל שאיחר'' הופך את הסיבה והתוצאה"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('41bd875a-4d01-4b99-a580-c120e1c8dfee', 'restatement', 'Although she was tired, she finished the report.', NULL, '[{"id": "a", "text": "She finished the report and then became tired."}, {"id": "b", "text": "She finished the report despite being tired."}, {"id": "c", "text": "She was tired because she finished the report."}, {"id": "d", "text": "She did not finish the report because she was tired."}]'::jsonb, 1, '{"strategy": "although tired...finished = למרות עייפות, סיימה בכל זאת.", "correct_reason": "''finished despite being tired'' = זהה למשמעות ''although tired, finished''.", "options_analysis": ["''סיימה ואז התעייפה'' משנה את סדר האירועים", "נכון! ''סיימה למרות העייפות'' = אותה משמעות בדיוק", "''התעייפה בגלל שסיימה'' הופך סדר סיבתי שלא קיים במקור", "''לא סיימה'' סותר את המקור — היא כן סיימה"]}', 1.54, -1.0, 0.25, 2, 'ai', NULL, true),
('84689fd7-5580-418e-a5e0-a7e89a9456e6', 'restatement', 'The shop was crowded, so we left quickly.', NULL, '[{"id": "a", "text": "The shop was empty, so we left."}, {"id": "d", "text": "We stayed in the shop because it was crowded."}, {"id": "c", "text": "We left quickly because the shop was crowded."}, {"id": "b", "text": "We left slowly because the shop was crowded."}]'::jsonb, 2, '{"strategy": "crowded, so left = צפוף, לכן עזבנו. סיבה-תוצאה.", "correct_reason": "''left quickly because crowded'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["''ריקה'' סותר ''crowded''", "''נשארנו'' סותר ''we left''", "נכון! אותה סיבה-תוצאה בדיוק כמו במקור", "''עזבנו לאט'' סותר ''left quickly''"]}', 1.59, -1.0, 0.25, 2, 'ai', NULL, true),
('3b571d29-e3cd-4fc8-8b2b-242e38223b78', 'restatement', 'He can swim, but he cannot dive.', NULL, '[{"id": "a", "text": "He can both swim and dive."}, {"id": "c", "text": "He can dive, but he cannot swim."}, {"id": "d", "text": "He can neither swim nor dive."}, {"id": "b", "text": "He is able to swim, yet he is unable to dive."}]'::jsonb, 3, '{"strategy": "can swim, cannot dive = יכול לשחות, לא יכול לצלול. שתי עובדות נפרדות.", "correct_reason": "''able to swim, unable to dive'' = אותן שתי עובדות בדיוק, בניסוח אחר.", "options_analysis": ["''יכול את שניהם'' סותר את חוסר היכולת לצלול", "''הפוך'' — במקור הוא כן יכול לשחות, לא לצלול", "''לא יכול אף אחד מהם'' סותר את היכולת לשחות", "נכון! שתי העובדות זהות: יכול לשחות, לא יכול לצלול"]}', 0.99, -1.0, 0.25, 2, 'ai', NULL, true),
('1cabab2f-4503-4588-bb2c-7f32c19b923b', 'restatement', 'As soon as the bell rang, the students left the classroom.', NULL, '[{"id": "c", "text": "The students left the classroom immediately after the bell rang."}, {"id": "d", "text": "The bell rang after the students left."}, {"id": "b", "text": "The students left the classroom before the bell rang."}, {"id": "a", "text": "The students stayed in the classroom after the bell rang."}]'::jsonb, 0, '{"strategy": "as soon as = מיד כאשר. הפעמון צלצל ומיד אחריו יצאו.", "correct_reason": "''left immediately after the bell rang'' = אותו רצף אירועים וזמן בדיוק.", "options_analysis": ["נכון! אותו רצף אירועים: פעמון ואז יציאה מיידית", "''הפעמון צלצל אחרי שיצאו'' הופך את סדר האירועים", "''יצאו לפני שהפעמון צלצל'' הופך את סדר האירועים", "''נשארו אחרי שהפעמון צלצל'' סותר לגמרי את המקור"]}', 1.23, -1.0, 0.25, 2, 'ai', NULL, true),
('391dad7e-a043-4c0b-b2bf-b089f24770ca', 'restatement', 'She works as a nurse in a large hospital.', NULL, '[{"id": "b", "text": "She is a patient in a large hospital."}, {"id": "d", "text": "She is employed as a nurse at a large hospital."}, {"id": "c", "text": "She manages a large hospital."}, {"id": "a", "text": "She used to work as a nurse but does not anymore."}]'::jsonb, 1, '{"strategy": "works as a nurse = עובדת כאחות. תפקיד נוכחי, לא עבר.", "correct_reason": "''employed as a nurse at a large hospital'' = אותה עובדה בדיוק בהווה.", "options_analysis": ["''מטופלת'' משנה לגמרי את התפקיד", "נכון! אותה עובדה בדיוק: מועסקת כאחות בבית חולים גדול", "''מנהלת'' משנה את התפקיד המקורי", "''עבדה בעבר אבל כבר לא'' סותר את הזמן ההווה במקור"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('e9a34e74-43d1-43d4-9cf9-aebe76419a71', 'restatement', 'Even though it was expensive, they bought the car.', NULL, '[{"id": "d", "text": "The car was expensive, so they sold it."}, {"id": "a", "text": "They bought the car because it was cheap."}, {"id": "c", "text": "They bought the car despite its high price."}, {"id": "b", "text": "They did not buy the car because it was expensive."}]'::jsonb, 2, '{"strategy": "even though expensive...bought = למרות המחיר הגבוה, קנו בכל זאת.", "correct_reason": "''bought despite its high price'' = זהה למשמעות ''even though expensive, bought''.", "options_analysis": ["''מכרו'' פועל שונה לגמרי מ-''קנו''", "''קנו כי היה זול'' סותר ''expensive''", "נכון! ''קנו למרות המחיר הגבוה'' = אותה משמעות בדיוק", "''לא קנו'' סותר את המקור — הם כן קנו"]}', 1.25, -1.0, 0.25, 2, 'ai', NULL, true),
('3e3468d7-2306-4f09-adbf-759a90e55a2b', 'restatement', 'The meeting was cancelled because the manager was sick.', NULL, '[{"id": "a", "text": "The meeting continued even though the manager was sick."}, {"id": "d", "text": "The meeting was cancelled, so the manager got sick."}, {"id": "b", "text": "The manager cancelled his illness."}, {"id": "c", "text": "The manager''s illness caused the meeting to be cancelled."}]'::jsonb, 3, '{"strategy": "cancelled because sick = בוטלה בגלל מחלה. סיבה-תוצאה.", "correct_reason": "''illness caused cancellation'' = אותה סיבה-תוצאה בדיוק, בניסוח שם-עצם.", "options_analysis": ["''המשיכה למרות המחלה'' סותר ''cancelled''", "הופך את סדר הסיבה והתוצאה", "משפט חסר משמעות הגיונית", "נכון! אותה סיבה-תוצאה: מחלת המנהל ביטלה את הפגישה"]}', 1.04, -1.0, 0.25, 2, 'ai', NULL, true),
('5f383911-7f7f-4f10-b5d7-1751fcbce237', 'restatement', 'He works hard so that he can support his family.', NULL, '[{"id": "b", "text": "He works hard in order to support his family."}, {"id": "a", "text": "He does not work hard, but he supports his family."}, {"id": "c", "text": "He works hard because his family supports him."}, {"id": "d", "text": "He supports his family instead of working hard."}]'::jsonb, 0, '{"strategy": "so that = כדי ש-. עובד קשה למטרה מסוימת.", "correct_reason": "''works hard in order to support'' = אותה מטרה בדיוק כמו ''so that he can support''.", "options_analysis": ["נכון! אותה מטרה בדיוק: עובד קשה כדי לתמוך במשפחה", "סותר ''works hard'' במקור", "הופך את כיוון התמיכה — במקור הוא תומך במשפחה, לא להפך", "סותר לגמרי — במקור הוא עובד קשה כדי לתמוך"]}', 1.07, -1.0, 0.25, 2, 'ai', NULL, true),
('129dfba6-74a2-4dcd-8387-49b7bce70d4a', 'restatement', 'She rarely eats meat, but she loves fish.', NULL, '[{"id": "d", "text": "She often eats meat but dislikes fish."}, {"id": "c", "text": "She seldom eats meat, though she really enjoys fish."}, {"id": "a", "text": "She loves meat but rarely eats fish."}, {"id": "b", "text": "She never eats meat or fish."}]'::jsonb, 1, '{"strategy": "rarely eats meat, loves fish = לעיתים נדירות אוכלת בשר, אוהבת דגים.", "correct_reason": "''seldom eats meat, enjoys fish'' = אותה משמעות בדיוק (seldom=rarely).", "options_analysis": ["הפוך משמעות — ''often'' סותר ''rarely'', ו''dislikes'' סותר ''loves''", "נכון! seldom=rarely, אותה משמעות בדיוק", "הפוך תפקידים בין בשר לדגים", "סותר לגמרי — היא כן אוהבת דגים"]}', 0.95, -1.0, 0.25, 2, 'ai', NULL, true),
('e36bc99a-ee27-4e73-ae5a-66266e6877a8', 'restatement', 'The train was delayed, so many passengers missed their connections.', NULL, '[{"id": "a", "text": "The train was delayed, but no passengers missed their connections."}, {"id": "b", "text": "The train arrived early, so passengers missed their connections."}, {"id": "d", "text": "Because the train was delayed, many passengers missed their connections."}, {"id": "c", "text": "Passengers missed their connections, which delayed the train."}]'::jsonb, 2, '{"strategy": "delayed, so missed connections = איחור גרם לפספוס קשרים.", "correct_reason": "''because delayed, missed connections'' = אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר לגמרי — במקור נוסעים כן פספסו", "''הגיעה מוקדם'' סותר ''delayed''", "נכון! אותה סיבה-תוצאה בדיוק כמו במקור", "הופך את סדר הסיבה והתוצאה"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('bd182bbd-a19c-4f06-b524-f8cc8888c25e', 'restatement', 'He apologized for arriving late to the interview.', NULL, '[{"id": "d", "text": "He refused to apologize for arriving late."}, {"id": "a", "text": "He apologized for missing the interview completely."}, {"id": "b", "text": "He arrived early and apologized anyway."}, {"id": "c", "text": "He said sorry for being late to the interview."}]'::jsonb, 3, '{"strategy": "apologized for arriving late = התנצל על איחור.", "correct_reason": "''said sorry for being late'' = אותה פעולה בדיוק, ניסוח שונה.", "options_analysis": ["''סירב להתנצל'' הפוך למקור", "''החסיר לגמרי'' משנה את העובדה — הוא כן הגיע, רק איחר", "''הגיע מוקדם'' סותר ''arriving late''", "נכון! אותה פעולה בדיוק: התנצל על איחור"]}', 1.53, -1.0, 0.25, 2, 'ai', NULL, true),
('72f37b7b-9a11-4d38-90d1-5a5488772653', 'reading_comprehension', 'What is the passage mainly about?', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "c", "text": "How and why families are recycling more at home"}, {"id": "a", "text": "How cities collect general household waste"}, {"id": "b", "text": "Why plastic is more useful than paper"}, {"id": "d", "text": "The history of landfills around the world"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה מתארת את מגמת המחזור הביתי ואת הסיבות לכך.", "correct_reason": "כל הפסקה עוסקת בהרגלי מחזור משפחתיים ובתועלות שלהם.", "options_analysis": ["נכון! מגמת המחזור הביתי והסיבות לה = הנושא הכולל", "הפוך — הפסקה עוסקת דווקא בהפרדת פסולת, לא איסוף כללי", "לא הנושא, ואינו מוזכר כהשוואה כזו", "פרט לא רלוונטי, לא מוזכר בפסקה"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('b6034c99-02ec-4b1f-8351-b0c2ea576a20', 'reading_comprehension', 'What do some cities offer to encourage recycling?', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "b", "text": "Money paid directly to each family"}, {"id": "a", "text": "Lower waste fees for households that recycle consistently"}, {"id": "c", "text": "Extra trash bins for every household"}, {"id": "d", "text": "Free new products made from recycled materials"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התמריץ שמוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''lower waste fees, to households that recycle consistently''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('81492565-8cd5-4395-9fce-c52ec459ebf1', 'reading_comprehension', 'According to the passage, what materials do families separate?', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "a", "text": "Only paper and plastic"}, {"id": "c", "text": "Only glass and metal"}, {"id": "d", "text": "Paper, plastic, glass, and food waste"}, {"id": "b", "text": "Clothes and electronics"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש רשימה מדויקת בפסקה.", "correct_reason": "הפסקה אומרת: ''separate paper, plastic, glass, and food waste''.", "options_analysis": ["חלקי בלבד — הפסקה מזכירה עוד חומרים", "לא נאמר בפסקה כלל", "נכון! רשימה מלאה כפי שמופיעה בפסקה", "לא נאמר בפסקה כלל"]}', 1.47, -1.0, 0.25, 2, 'ai', NULL, true),
('716be8b5-07fd-4aba-9643-5f6d549fce90', 'reading_comprehension', 'The word "consistently" in the passage most closely means:', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "a", "text": "carelessly and randomly"}, {"id": "c", "text": "quickly and briefly"}, {"id": "d", "text": "occasionally and rarely"}, {"id": "b", "text": "regularly and continuously"}]'::jsonb, 3, '{"strategy": "אוצר מילים בהקשר — ''households that recycle consistently'' מתייחס להרגל קבוע.", "correct_reason": "consistently = באופן עקבי וקבוע לאורך זמן.", "options_analysis": ["הפוך — עקביות היא ההפך מאקראיות", "לא מתאר משך זמן, אלא קביעות", "הפוך — ''לעיתים נדירות'' סותר עקביות", "נכון! consistently = באופן קבוע ועקבי"]}', 1.27, -1.0, 0.25, 2, 'ai', NULL, true),
('e72a7c5a-1ce4-4cbf-af68-d57c753e2a10', 'reading_comprehension', 'Why does recycling usually save energy, according to the passage?', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "c", "text": "Making products from recycled materials often requires less power than using raw materials"}, {"id": "d", "text": "Recycled materials do not need to be transported"}, {"id": "a", "text": "Landfills produce their own energy"}, {"id": "b", "text": "Recycling centers use solar power exclusively"}]'::jsonb, 0, '{"strategy": "שאלת פרט/הבנה — חפש את ההסבר לחיסכון באנרגיה.", "correct_reason": "הפסקה אומרת: ''making new products from recycled materials usually requires less power than making them from raw materials''.", "options_analysis": ["נכון! ההסבר המדויק מהפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה — הפוך, נאמר שהם שולחים לשם פחות פסולת", "לא נאמר בפסקה"]}', 1.1, -1.0, 0.25, 2, 'ai', NULL, true),
('dca42b5b-fc14-4c7e-bd3f-8c2c5514a5ea', 'reading_comprehension', 'Why do many communities provide sorting guides?', 'f8a8e734-a2ca-41b9-a36c-63541469ef94', '[{"id": "c", "text": "Because sorting waste is required by international law"}, {"id": "a", "text": "Because recycling only works well if people sort their waste correctly"}, {"id": "d", "text": "Because recycling centers refuse unsorted waste entirely"}, {"id": "b", "text": "Because guides help people find nearby recycling centers"}]'::jsonb, 1, '{"strategy": "שאלת סיבה — חפש את המשפט האחרון בפסקה.", "correct_reason": "הפסקה אומרת: ''recycling only works well if people sort their waste correctly, so many communities provide guides''.", "options_analysis": ["לא נאמר בפסקה כלל", "נכון! הסיבה המדויקת שמופיעה בפסקה", "לא נאמר בפסקה — ניסוח קיצוני מדי", "לא זו הסיבה שניתנה בפסקה"]}', 1.31, -1.0, 0.25, 2, 'ai', NULL, true),
('a0c9e5fa-713a-4647-b0f2-50fae749a6fb', 'reading_comprehension', 'What is the passage mainly about?', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "d", "text": "How to build online chat tools"}, {"id": "b", "text": "A history of office buildings"}, {"id": "c", "text": "The growth of remote work and its benefits and challenges"}, {"id": "a", "text": "Why commuting is always better than remote work"}]'::jsonb, 2, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את התפתחות העבודה מהבית ואת היתרונות והאתגרים שלה.", "correct_reason": "הפסקה כולה עוסקת בהתפתחות העבודה מרחוק ובשני הצדדים שלה.", "options_analysis": ["פרט טכני שמוזכר, לא הנושא המרכזי", "לא הנושא, לא מוזכר בפסקה", "נכון! התפתחות העבודה מרחוק + יתרונות ואתגרים = הנושא הכולל", "הפוך — הפסקה לא טוענת עמדה כזו"]}', 0.99, -1.0, 0.25, 2, 'ai', NULL, true),
('59cfb17d-4df6-445b-aa82-38fca752ce63', 'reading_comprehension', 'What caused remote work to become especially common?', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "d", "text": "A new law requiring companies to allow remote work"}, {"id": "c", "text": "Employees demanding higher salaries"}, {"id": "a", "text": "A shortage of office space in cities"}, {"id": "b", "text": "Businesses being forced to adapt during a global health crisis"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הסיבה המוזכרת בפסקה.", "correct_reason": "הפסקה אומרת: ''became especially common after many businesses were forced to adapt during a global health crisis''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.39, -1.0, 0.25, 2, 'ai', NULL, true),
('7c070b4d-6c74-44a9-8488-252bcba8aa4d', 'reading_comprehension', 'According to the passage, what is one benefit employees report from remote work?', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "c", "text": "Saving time on commuting"}, {"id": "b", "text": "Free equipment from their employer"}, {"id": "d", "text": "Higher salaries than office workers"}, {"id": "a", "text": "Fewer working hours overall"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש רשימת יתרונות בפסקה.", "correct_reason": "הפסקה אומרת: ''including saving time on commuting and having more flexibility''.", "options_analysis": ["נכון! נאמר במפורש כיתרון", "לא נאמר בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.34, -1.0, 0.25, 2, 'ai', NULL, true),
('37a282fd-a8a0-484c-9778-45c360c3ce66', 'reading_comprehension', 'The word "isolated" in the passage most closely means:', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "b", "text": "extremely busy and overwhelmed"}, {"id": "d", "text": "alone and disconnected from others"}, {"id": "a", "text": "well organized and efficient"}, {"id": "c", "text": "financially secure"}]'::jsonb, 1, '{"strategy": "אוצר מילים בהקשר — ''feel isolated without daily face-to-face contact''.", "correct_reason": "isolated = מבודד/מנותק מאחרים, כתוצאה מחוסר מגע יומיומי.", "options_analysis": ["לא קשור לעומס עבודה", "נכון! isolated = מבודד/מנותק מאנשים אחרים", "הפוך גמור למשמעות המילה", "לא קשור לביטחון כלכלי"]}', 1.42, -1.0, 0.25, 2, 'ai', NULL, true),
('29514ea3-1e92-49e2-b8b1-83b4fbca27b5', 'reading_comprehension', 'What challenge do managers sometimes face with remote work?', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "b", "text": "Paying employees on time"}, {"id": "a", "text": "Finding enough remote workers to hire"}, {"id": "d", "text": "Finding it harder to monitor progress on team projects"}, {"id": "c", "text": "Keeping the office building secure"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את האתגר של מנהלים בפסקה.", "correct_reason": "הפסקה אומרת: ''managers sometimes find it harder to monitor progress on team projects''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש כאתגר למנהלים", "לא נאמר בפסקה"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('05f2b646-7ec9-4e07-a15e-ab66f8aca9eb', 'reading_comprehension', 'Why do some companies require staff to come into the office a few days a week?', 'd9107a8f-ea0f-428f-8e2b-8f47484407aa', '[{"id": "b", "text": "Because remote work is illegal in most countries"}, {"id": "d", "text": "Because employees prefer commuting"}, {"id": "a", "text": "Because video calls do not work well for meetings"}, {"id": "c", "text": "To help address the isolation and monitoring challenges of remote work"}]'::jsonb, 3, '{"strategy": "שאלת מטרה — חפש את ההיגיון מאחורי ההוראה המוזכרת בסוף הפסקה.", "correct_reason": "הפסקה מקשרת בין האתגרים (בידוד, קושי במעקב) לפתרונות, כולל ימי נוכחות בעבודה.", "options_analysis": ["לא נאמר בפסקה, וגם לא נכון עובדתית", "לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! הפתרון המעשי לאתגרים שתוארו קודם בפסקה"]}', 1.47, -1.0, 0.25, 2, 'ai', NULL, true);